Base.@__doc__ primitive type Fruit <: Enum{Int32} 32 end
function Fruit(x::Integer)
    0 <= x <= 1 || Base.Enums.enum_argument_error(:Fruit, x)
    return Base.Enums.bitcast(Fruit, convert(Int32, x))
end
function (Base.Enums.Enums).namemap(::Type{Fruit})
    Dict{Int32, Symbol}(1 => :banana, 0 => :apple)
end
function Base.typemin(x::Type{Fruit})
    Fruit(0)
end
function Base.typemax(x::Type{Fruit})
    Fruit(1)
end
let type_hash = hash(Fruit)
    function (Base.Enums.Enums)._enum_hash(x::Fruit, h::UInt)
        hash(type_hash, hash(Integer(x), h))
    end
end
let insts = (Any[Fruit(v) for v = Int32[0, 1]]...,)
    function Base.instances(::Type{Fruit})
        insts
    end
end
const banana = Fruit(1)
const apple = Fruit(0)
nothing
